#include "game/world12/codec.hpp"
#include "game/world12/save.hpp"
#include "game/world12/match_projection.hpp"
#include <set>
#include <iostream>
#include <stdexcept>
using namespace bmh::world12;
void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
World synthetic(){World w;uint32_t club=0,player=4000;for(uint32_t l=0;l<14;++l){auto&m=w.membership[l];m.league={l};for(int c=0;c<w.catalogue.leagues[l].clubs;++c){ClubRecord record;record.id={club};record.country=w.catalogue.leagues[l].country;record.league={l};record.name="Club "+std::to_string(club);record.crest={club+700};w.crests.emplace(record.crest,CrestResource{"W/"+std::to_string(club/8)+".VGA",uint8_t(club%8)});for(int p=0;p<20;++p){PlayerRecord person;person.id={player};person.attributes={"Player "+std::to_string(player),50u|(60u<<7)|(65u<<14),0,0};w.players.emplace(person.id,person);record.roster[size_t(p)]={person.id,uint16_t(p<11?RosterFlag::lineup:RosterFlag::reserve)};++player;}m.clubs.push_back(record.id);w.clubs.emplace(record.id,record);++club;}}
 return w;}
int main()try{
 auto catalogue=Catalogue::dual_classic();check(catalogue.league_clubs()==252,"league club total");check(catalogue.table_leagues(TableGroup::germany).size()==5&&catalogue.table_leagues(TableGroup::england).size()==5&&catalogue.table_leagues(TableGroup::europe).size()==4,"table groups");check(catalogue.starting_league(Country::england,4).value==9&&catalogue.league({9}).rounds()==18,"English fifth league schedule size");check(catalogue.league({13}).country==Country::portugal&&!catalogue.league({13}).playable,"Portugal replaced English foreign slot");
 bool rejected=false;try{catalogue.starting_league(Country::portugal,0);}catch(...){rejected=true;}check(rejected,"AI country selectable");
 auto w=synthetic();w.managers={{0,"DE",{0},{0},0},{1,"EN",{90},{5},1}};w.validate();check(w.manager_country(0)==Country::germany&&w.manager_country(1)==Country::england,"mixed manager countries");auto raw=bmh::world12::encode_world(w);auto decoded=decode_world(raw);check(decoded==w,"wide world database roundtrip");check(decoded.players.contains({4095})&&decoded.players.contains({9039})&&decoded.crests.contains({700}),"wide IDs were truncated or treated as old sentinels");
 auto high=w;auto person=high.players.extract(PlayerId{4000});person.key()={1000000};person.mapped().id={1000000};high.players.insert(std::move(person));high.clubs.at({0}).roster[0].player={1000000};check(decode_world(encode_world(high))==high,"large ID mapping lost");
 auto loan=w;auto player=loan.clubs.at({0}).roster[0].player;auto substitute=loan.clubs.at({90}).roster[0].player;loan.clubs.at({0}).roster[0].player=substitute;loan.clubs.at({90}).roster[0].player=player;loan.loans.push_back({player,{0},{90},12});check(decode_world(encode_world(loan))==loan,"cross-country loan lost references");
 auto ten=w.catalogue.league({9});std::set<std::pair<uint32_t,uint32_t>> pairs;for(int round=1;round<=ten.rounds();++round){auto fixtures=league_fixtures(w,{9},round);check(fixtures.size()==5,"ten-team round has wrong match count");std::set<ClubId> played;for(const auto&f:fixtures){check(f.home!=f.away&&played.insert(f.home).second&&played.insert(f.away).second,"club plays twice in a round");check(pairs.emplace(f.home.value,f.away.value).second,"duplicate home-away fixture");}}check(pairs.size()==90,"ten-team season is not complete");
 CareerSnapshot state;state.world=w;state.results=SeasonResults::empty(w.catalogue);state.date=731;state.season=2;state.watcom_seed=0xfffffff1u;state.game_seed=-19;state.league_rounds[9]=18;state.results.result(w.catalogue,{9},18,4)={true,2,1};auto saved=make_save(state);check(read_save(saved)==state,"O1.2 snapshot roundtrip lost wide IDs or seeds");saved.version="O1.1";bool old_rejected=false;try{read_save(saved);}catch(...){old_rejected=true;}check(old_rejected,"old save interpreted as dual world");
 auto ai=high;ai.managers.clear();bmh::GameState base;base.club_ids.resize(445);base.team_flags.resize(445);base.team_morale.resize(445);auto projection=AiMatchProjection::create(ai,{{0},{251}},base);check(projection.global_player(0).value==1000000&&projection.local_player({1000000})==0,"wide player failed local projection");check(projection.global_club(1).value==251,"club identity lost in projection");projection.state.players[0].w35c=(projection.state.players[0].w35c&~127u)|72u;projection.commit_player_attributes(ai);check(ai.players.at({1000000}).attributes.form()==72&&ai.players.at({9039}).attributes.form()==w.players.at({9039}).attributes.form(),"local mutation mapped to wrong player");
 bool human_blocked=false;try{AiMatchProjection::create(w,{{0},{90}},base);}catch(...){human_blocked=true;}check(human_blocked,"unimplemented human projection silently accepted");
 auto bad=w;bad.membership[5].clubs[0]={0};rejected=false;try{bad.validate();}catch(...){rejected=true;}check(rejected,"cross-country or duplicate membership accepted");
 bad=w;bad.clubs.at({1}).roster[0].player=bad.clubs.at({0}).roster[0].player;rejected=false;try{bad.validate();}catch(...){rejected=true;}check(rejected,"duplicate roster player accepted");
 rejected=false;try{w.national_coach_country(0);}catch(...){rejected=true;}check(rejected,"multiplayer national coach restriction lost");w.managers.erase(w.managers.begin());check(w.national_coach_country(1)==Country::england,"English national coach mapped to Germany");
 raw.pop_back();rejected=false;try{decode_world(raw);}catch(...){rejected=true;}check(rejected,"truncated world database accepted");
 std::cout<<"14 leagues, mixed countries, >4095 player IDs, >511 crests, loans and typed codec passed\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
